def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending in s whose digits are at most limit."""
    if start > finish or finish < 1:
        return 0
    if any(not ch.isdigit() or int(ch) > limit for ch in s):
        return 0

    def count_prefixes_leq(target: str, include_equal: bool) -> int:
        """Count valid, non-leading-zero prefixes of target's length up to target."""
        length = len(target)
        total = 0
        for i, char in enumerate(target):
            digit = int(char)
            low = 1 if i == 0 else 0
            choices_below = max(0, min(limit, digit - 1) - low + 1)
            remaining = length - i - 1
            total += choices_below * ((limit + 1) ** remaining)
            if digit < low or digit > limit:
                return total
        if include_equal:
            total += 1
        return total

    suffix_value = int(s)

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        bound_text = str(bound)
        suffix_length = len(s)
        result = 0
        # Every possible decimal length shorter than the bound has a free prefix.
        for length in range(suffix_length, len(bound_text)):
            prefix_length = length - suffix_length
            if prefix_length == 0:
                if s[0] != "0":
                    result += 1
            else:
                result += limit * ((limit + 1) ** (prefix_length - 1))

        length = len(bound_text)
        if length < suffix_length:
            return result
        prefix_length = length - suffix_length
        if prefix_length == 0:
            # The integer's usual representation cannot start with a zero.
            if s[0] != "0" and suffix_value <= bound and len(str(suffix_value)) == length:
                result += 1
            return result

        prefix_bound = bound_text[:prefix_length]
        suffix_bound = bound_text[prefix_length:]
        include_equal = s <= suffix_bound
        result += count_prefixes_leq(prefix_bound, include_equal)
        return result

    return count_up_to(finish) - count_up_to(start - 1)

