from functools import lru_cache


def _count_beautiful_up_to(x: int) -> int:
    """Count beautiful positive integers no greater than x."""
    if x <= 0:
        return 0

    digits = list(map(int, str(x)))
    good_no_zero = 0

    # A number containing a zero has product zero and positive digit sum, so
    # it is automatically beautiful. Count the qualifying zero-free numbers
    # separately, and add all zero-containing numbers afterward.
    for length in range(1, len(digits) + 1):
        bound = digits if length == len(digits) else [9] * length

        for target_sum in range(1, 9 * length + 1):
            @lru_cache(maxsize=None)
            def dp(pos: int, digit_sum: int, product_mod: int, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if pos == length:
                    return int(digit_sum == target_sum and product_mod == 0)

                upper = bound[pos] if tight else 9
                first_digit = 1  # Exclude leading zeroes from the digit product.
                ways = 0
                for digit in range(first_digit, upper + 1):
                    next_sum = digit_sum + digit
                    if next_sum <= target_sum:
                        ways += dp(
                            pos + 1,
                            next_sum,
                            (product_mod * digit) % target_sum,
                            tight and digit == upper,
                        )
                return ways

            good_no_zero += dp(0, 0, 1 % target_sum, True)

    @lru_cache(maxsize=None)
    def count_no_zero(pos: int, tight: bool) -> int:
        if pos == len(digits):
            return 1
        upper = digits[pos] if tight else 9
        return sum(
            count_no_zero(pos + 1, tight and digit == upper)
            for digit in range(1, upper + 1)
        )

    no_zero_total = sum(9 ** length for length in range(1, len(digits)))
    no_zero_total += count_no_zero(0, True)
    return x - no_zero_total + good_no_zero


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count the number of beautiful numbers in [l, r] inclusive.

    A positive integer is beautiful if the product of its digits is divisible
    by the sum of its digits.

    Constraints:
        1 <= l <= r < 10^9
    """
    return _count_beautiful_up_to(r) - _count_beautiful_up_to(l - 1)

