MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid with H rows and W columns of '1', '2', '3', and '?',
    count replacements of '?' such that edge-sharing cells differ.

    Return the count modulo 998244353.
    """
    # Use the shorter dimension as the transfer width.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    allowed = []
    for row in grid:
        masks = []
        for ch in row:
            if ch == '?':
                masks.append(7)
            elif ch in '123':
                masks.append(1 << (ord(ch) - ord('1')))
            else:
                return 0
        allowed.append(masks)

    # Enumerate every horizontally proper row assignment once.
    states = []
    digits = []

    def enumerate_rows(pos, prev, code, ds):
        if pos == W:
            states.append(code)
            digits.append(ds)
            return
        for color in range(3):
            if color != prev:
                enumerate_rows(pos + 1, color, code * 3 + color, ds + (color,))

    enumerate_rows(0, -1, 0, ())
    index = {code: i for i, code in enumerate(states)}

    # Initialize counts using the constraints in the first row.
    dp = [0] * len(states)
    for i, row in enumerate(digits):
        if all(allowed[0][col] & (1 << color) for col, color in enumerate(row)):
            dp[i] = 1

    for r in range(1, H):
        ndp = [0] * len(states)
        for i, value in enumerate(dp):
            if not value:
                continue
            old = digits[i]
            chosen = [0] * W

            # Visit only assignments differing from the cell above and
            # from the previous cell in this row.
            def extend(pos, code):
                if pos == W:
                    j = index[code]
                    ndp[j] = (ndp[j] + value) % MOD
                    return
                forbidden = old[pos]
                for color in range(3):
                    if (allowed[r][pos] & (1 << color)
                            and color != forbidden
                            and (pos == 0 or color != chosen[pos - 1])):
                        chosen[pos] = color
                        extend(pos + 1, code * 3 + color)

            extend(0, 0)
        dp = ndp

    return sum(dp) % MOD

