def can_color_all_points(n: int, k: int) -> bool:
    """ Alice and Bob are on a circle with n equally spaced points numbered 0 to n-1.
    Alice is at point 0, Bob is at point k. Initially all points are white.

    Starting with Alice, they alternately color one white point black, with the constraint
    that after coloring, the pattern must be symmetric with respect to the line connecting
    the player to the center of the circle.

    Both players cooperate to maximize the total number of colored points.

    Args:
        n: Number of points on the circle (2 <= n <= 2*10^5)
        k: Bob's position (1 <= k <= n-1)

    Returns:
        True if all points can be colored black, False otherwise

    >>> can_color_all_points(6, 2)
    True
    >>> can_color_all_points(6, 3)
    False
    >>> can_color_all_points(6, 1)
    True
    """
    def reflect(point: int, center: int) -> int:
        return (2 * center - point) % n

    def fixed_points(center: int) -> tuple[int, ...]:
        first = center % n
        if n % 2:
            return (first,)
        return (first, (first + n // 2) % n)

    fixed_a = fixed_points(0)
    fixed_b = fixed_points(k)

    # For each reflection, unmatched contains the colored endpoint of every
    # pair that currently has exactly one black point.
    pending = [(bytearray(n), set(), set(), 0, None)]
    while pending:
        black, unmatched_a, unmatched_b, turn, forced = pending.pop()
        while turn < n:
            center = 0 if turn % 2 == 0 else k
            unmatched = unmatched_a if center == 0 else unmatched_b

            if len(unmatched) > 1:
                break
            if len(unmatched) == 1:
                endpoint = next(iter(unmatched))
                choices = (reflect(endpoint, center),)
            else:
                fixed = fixed_a if center == 0 else fixed_b
                choices = tuple(point for point in fixed if not black[point])

            if forced is not None:
                choices = (forced,)
                forced = None
            if not choices:
                break

            if len(choices) > 1:
                for point in choices[1:]:
                    pending.append((black.copy(), unmatched_a.copy(),
                                    unmatched_b.copy(), turn, point))

            point = choices[0]
            if black[point]:
                break
            black[point] = 1

            partner_a = reflect(point, 0)
            if partner_a != point:
                if black[partner_a]:
                    unmatched_a.remove(partner_a)
                else:
                    unmatched_a.add(point)

            partner_b = reflect(point, k)
            if partner_b != point:
                if black[partner_b]:
                    unmatched_b.remove(partner_b)
                else:
                    unmatched_b.add(point)

            turn += 1

        if turn == n:
            return True

    return False

