from typing import List, Tuple
from functools import lru_cache

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki alternate playing a hand card and optionally taking a
    smaller card from the table. The player unable to make a move loses.
    """
    @lru_cache(None)
    def winning(hand0: Tuple[int, ...], hand1: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = hand0 if turn == 0 else hand1
        if not hand:
            return False
        other = hand1 if turn == 0 else hand0
        for i, card in enumerate(hand):
            remainder = hand[:i] + hand[i + 1:]
            newtable = tuple(sorted(table + (card,)))
            if turn == 0:
                if not winning(remainder, other, newtable, 1):
                    return True
            else:
                if not winning(other, remainder, newtable, 0):
                    return True
            for j, take in enumerate(table):
                if take < card:
                    newhand = tuple(sorted(remainder + (take,)))
                    newtable = tuple(sorted(table[:j] + table[j + 1:] + (card,)))
                    if turn == 0:
                        if not winning(newhand, other, newtable, 1):
                            return True
                    else:
                        if not winning(other, newhand, newtable, 0):
                            return True
        return False
    return "Takahashi" if winning(tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)), 0) else "Aoki"

