def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3."""
    mod = 998244353

    # For n = prod(p**e), the number of ordered M-tuples with product n is
    # prod binom(M+e-1, e). The divisor sum is multiplicative modulo 3:
    # p == 0: local factor is 1; p == 1: it is e+1; p == 2: it is
    # zero for odd e and 1 for even e.
    limit = int(N**0.5)
    while (limit + 1) * (limit + 1) <= N:
        limit += 1
    while limit * limit > N:
        limit -= 1
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    max_e = N.bit_length()
    weights = [1] * (max_e + 1)
    for e in range(1, max_e + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % mod * pow(e, mod - 2, mod) % mod

    block_size = 100_000
    answer = 0
    for lo in range(1, N + 1, block_size):
        hi = min(N + 1, lo + block_size)
        rem = list(range(lo, hi))
        good = bytearray(hi - lo)
        value = [1] * (hi - lo)
        for p in primes:
            first = ((lo + p - 1) // p) * p
            for x in range(first, hi, p):
                i = x - lo
                e = 0
                while rem[i] % p == 0:
                    rem[i] //= p
                    e += 1
                if e:
                    value[i] = value[i] * weights[e] % mod
                    if (p % 3 == 1 and e % 3 == 2) or (p % 3 == 2 and e % 2 == 1):
                        good[i] = 1
        for i, r in enumerate(rem):
            if r > 1:
                value[i] = value[i] * weights[1] % mod
                if r % 3 == 2:
                    good[i] = 1
            if good[i]:
                answer += value[i]
        answer %= mod
    return answer

