def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """ Count the number of integers x such that num1 <= x <= num2 and
    min_sum <= digit_sum(x) <= max_sum, where digit_sum(x) is the sum of digits.

    Return the count modulo 10^9 + 7.
    """
    mod = 1_000_000_007

    def count_at_most(bound: str) -> int:
        if not bound or bound == "0":
            return 0
        # Leading zeroes let this count every nonnegative integer up to bound.
        tight = [0] * (max_sum + 1)
        loose = [0] * (max_sum + 1)
        tight[0] = 1
        for ch in bound:
            digit = ord(ch) - ord("0")
            next_tight = [0] * (max_sum + 1)
            next_loose = [0] * (max_sum + 1)
            for total, ways in enumerate(tight):
                if ways:
                    for d in range(min(digit, max_sum - total) + 1):
                        if d == digit:
                            next_tight[total + d] = (next_tight[total + d] + ways) % mod
                        else:
                            next_loose[total + d] = (next_loose[total + d] + ways) % mod
            for total, ways in enumerate(loose):
                if ways:
                    for d in range(min(9, max_sum - total) + 1):
                        next_loose[total + d] = (next_loose[total + d] + ways) % mod
            tight, loose = next_tight, next_loose
        return (sum(tight[min_sum:max_sum + 1]) +
                sum(loose[min_sum:max_sum + 1])) % mod

    def decrement(value: str) -> str:
        digits = list(value)
        i = len(digits) - 1
        while digits[i] == "0":
            digits[i] = "9"
            i -= 1
        digits[i] = chr(ord(digits[i]) - 1)
        return "".join(digits).lstrip("0") or "0"

    return (count_at_most(num2) - count_at_most(decrement(num1))) % mod

