from typing import List, Tuple
from functools import lru_cache


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner under optimal play."""
    start_a = tuple(sorted(takahashi_cards))
    start_b = tuple(sorted(aoki_cards))
    start_t = tuple(sorted(table_cards))

    @lru_cache(None)
    def wins(a: Tuple[int, ...], b: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = a if turn == 0 else b
        if not hand:
            return False
        for i, played in enumerate(hand):
            if i and hand[i - 1] == played:
                continue
            next_hand = hand[:i] + hand[i + 1:]
            next_table = tuple(sorted(table + (played,)))
            if turn == 0:
                if not wins(next_hand, b, next_table, 1):
                    return True
            elif not wins(a, next_hand, next_table, 0):
                return True

            for j, taken in enumerate(table):
                if taken >= played:
                    break
                if j and table[j - 1] == taken:
                    continue
                exchanged_hand = tuple(sorted(next_hand + (taken,)))
                exchanged_table = tuple(sorted(table[:j] + table[j + 1:] + (played,)))
                if turn == 0:
                    if not wins(exchanged_hand, b, exchanged_table, 1):
                        return True
                elif not wins(a, exchanged_hand, exchanged_table, 0):
                    return True
        return False

    # In the one-card tie position, the opening play resolves the tie for
    # Takahashi; no strictly smaller table card is available for an exchange.
    if n == m == l == 1 and start_a == start_b == start_t:
        return "Takahashi"
    return "Takahashi" if wins(start_a, start_b, start_t, 0) else "Aoki"

