from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given sections to monitor, return the least cost using the available sensors, or -1 if impossible."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # For each section, choose a sensor type and use the minimum count of
    # that type which covers the section. Keep global sensor limits in a DP.
    states = {(0, 0): 0}
    for distance in sections[:n]:
        need1 = (distance + l1 - 1) // l1
        need2 = (distance + l2 - 1) // l2
        options = []
        if need1 <= k1:
            options.append((need1, 0, need1 * c1))
        if need2 <= k2:
            options.append((0, need2, need2 * c2))
        updated = {}
        for (used1, used2), cost in states.items():
            for add1, add2, extra in options:
                total1, total2 = used1 + add1, used2 + add2
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    value = cost + extra
                    if value < updated.get(key, float('inf')):
                        updated[key] = value
        states = updated
        if not states:
            return -1
    return min(states.values()) if states else -1

