    """Calculate twice the black area in the repeating wallpaper pattern."""
    def primitive(x, y):
        qx, rx = divmod(x, 2)
        qy, ry = divmod(y, 2)
        total = 2 * (4 * qx * qy + 2 * qx * ry + 2 * qy * rx)
        left = min(rx, 1)
        if left > 0:
            t = max(0.0, min(left, 2 - ry))
            total += ry * t + (2 * left - left * left - (2 * t - t * t)) / 2
        if rx > 1:
            start = max(1, 2 - ry)
            if rx > start:
                total += (ry - 2) * (rx - start) + (rx * rx - start * start) / 2
        return total

    area = primitive(C, D) - primitive(A, D) - primitive(C, B) + primitive(A, B)
    return round(2 * area)

