from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether the available rectangles can exactly cover the grid."""
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False

    total = h * w
    full = (1 << total) - 1
    tile_areas = [a * b for a, b in tiles[:n]]
    if sum(tile_areas) < total:
        return False

    # Each possible placement is represented as a bit mask over grid cells.
    placements = []
    for a, b in tiles[:n]:
        shapes = {(a, b), (b, a)}
        tile_placements = {}
        for r in range(h):
            for c in range(w):
                masks = []
                for rh, cw in shapes:
                    if r + rh > h or c + cw > w:
                        continue
                    mask = 0
                    row_bits = (1 << cw) - 1
                    for rr in range(r, r + rh):
                        mask |= row_bits << (rr * w + c)
                    masks.append(mask)
                tile_placements[(r, c)] = tuple(set(masks))
        placements.append(tile_placements)

    # For a given occupied-cell mask and used-tile mask, the remainder is fixed.
    seen = set()

    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        state = (occupied, used)
        if state in seen:
            return False
        seen.add(state)

        # The first uncovered cell must be the top-left cell of its rectangle:
        # all earlier cells in row-major order are already covered.
        remaining = full ^ occupied
        first = (remaining & -remaining).bit_length() - 1
        r, c = divmod(first, w)

        for i, tile in enumerate(tiles[:n]):
            if used & (1 << i):
                continue
            for mask in placements[i][(r, c)]:
                if not (mask & occupied):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

