def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    from fractions import Fraction

    def clip(poly, a, b, c):
        if not poly:
            return []
        out = []
        px, py = poly[-1]
        pv = a * px + b * py - c
        for x, y in poly:
            cv = a * x + b * y - c
            if (cv <= 0) != (pv <= 0):
                t = pv / (pv - cv)
                out.append((px + t * (x - px), py + t * (y - py)))
            if cv <= 0:
                out.append((x, y))
            px, py, pv = x, y, cv
        return out

    def area(poly):
        if len(poly) < 3:
            return Fraction(0)
        return abs(sum(poly[i][0] * poly[(i + 1) % len(poly)][1]
                       - poly[(i + 1) % len(poly)][0] * poly[i][1]
                       for i in range(len(poly)))) / 2

    def local(xmax, ymax):
        # Work over a 4-by-4 tile and retain all three parity terms:
        # floor(x) + floor(y/2) + floor((x+y)/2).
        total = Fraction(0)
        for i in range(4):
            for q in range(2):
                for j in range(5):
                    if (i + q + j) & 1:
                        continue
                    p = [(Fraction(0), Fraction(0)), (Fraction(xmax), Fraction(0)),
                         (Fraction(xmax), Fraction(ymax)), (Fraction(0), Fraction(ymax))]
                    p = clip(p, -1, 0, -i)
                    p = clip(p, 1, 0, i + 1)
                    p = clip(p, 0, -1, -2 * q)
                    p = clip(p, 0, 1, 2 * q + 2)
                    p = clip(p, -1, -1, -2 * j)
                    p = clip(p, 1, 1, 2 * j + 2)
                    total += area(p)
        return total

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        # Each 4-by-4 tile is half black, hence has black area 8.
        return (qx * qy * 8 + qx * local(4, ry)
                + qy * local(rx, 4) + local(rx, ry))

    doubled = 2 * (prefix(C, D) - prefix(A, D)
                   - prefix(C, B) + prefix(A, B))
    return int(doubled)

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black-painted area inside a rectangle."""
    def clip(poly, a, b, c, keep_le):
        if not poly:
            return []
        out = []
        for p, q in zip(poly, poly[1:] + poly[:1]):
            vp = a * p[0] + b * p[1] - c
            vq = a * q[0] + b * q[1] - c
            inp = vp <= 0 if keep_le else vp >= 0
            inq = vq <= 0 if keep_le else vq >= 0
            if inp:
                out.append(p)
            if inp != inq:
                t = vp / (vp - vq)
                out.append((p[0] + t * (q[0] - p[0]),
                            p[1] + t * (q[1] - p[1])))
        return out

    def polygon_area(poly):
        return abs(sum(p[0] * q[1] - p[1] * q[0]
                       for p, q in zip(poly, poly[1:] + poly[:1]))) / 2

    def base_area(x, y):
        # In [0,4] x [0,2], color parity is floor(x)+floor((x+y)/2).
        area = 0.0
        for i in range(4):
            for k in range(3):
                poly = [(0.0, 0.0), (x, 0.0), (x, y), (0.0, y)]
                poly = clip(poly, 1, 0, float(i), False)
                poly = clip(poly, 1, 0, float(i + 1), True)
                poly = clip(poly, 1, 1, float(2 * k), False)
                poly = clip(poly, 1, 1, float(2 * k + 2), True)
                if poly and ((i + k) % 2 == 0):
                    area += polygon_area(poly)
        return area

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        # The pattern's periods are 4 horizontally and 2 vertically;
        # each full strip is half black.
        return 8 * qx * qy + 2 * qx * ry + 2 * qy * rx + base_area(rx, ry)

    return int(round(2 * (prefix(C, D) - prefix(A, D)
                          - prefix(C, B) + prefix(A, B))))

