def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by digit sum."""
    from functools import lru_cache

    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        width = len(digits)
        total = 0

        # Fixing the digit sum lets us track only the product modulo that sum.
        for target_sum in range(1, 9 * width + 1):
            @lru_cache(None)
            def visit(pos: int, digit_sum: int, product_mod: int, started: bool, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                remaining = width - pos
                if digit_sum + 9 * remaining < target_sum:
                    return 0
                if pos == width:
                    return int(started and digit_sum == target_sum and product_mod == 0)

                limit = digits[pos] if tight else 9
                result = 0
                for d in range(limit + 1):
                    next_tight = tight and d == limit
                    if not started and d == 0:
                        result += visit(pos + 1, digit_sum, 1 % target_sum, False, next_tight)
                    else:
                        result += visit(
                            pos + 1,
                            digit_sum + d,
                            (product_mod * d) % target_sum,
                            True,
                            next_tight,
                        )
                return result

            total += visit(0, 0, 1 % target_sum, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

