from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences whose only missing length-M subsequence is X."""
    if len(X) != M or any(v < 1 or v > K for v in X):
        return 0

    if M == 3 and K >= 3:
        u, v, w = (c - 1 for c in X)

        def surj(n, k):
            return sum((-1) ** j * comb(k, j) * pow(k - j, n, MOD)
                       for j in range(k + 1)) % MOD

        if u == v:
            d = K - 1
            one = [surj(i, d) for i in range(N + 1)]
            prefix = [0] * (N + 1)
            for q in range(1, N + 1):
                prefix[q] = sum(one[l] * one[q - 1 - l]
                                for l in range(q)) % MOD
        else:
            d = K - 2

            def side(n):
                total = 0
                for j in range(d + 1):
                    s = d - j
                    # All ordinary symbols occur; the special v (or u)
                    # occurs at least once in this side. Its marker supplies
                    # the other occurrence needed for the diagonal pair.
                    count = pow(s + 1, n, MOD) - pow(s, n, MOD)
                    total += (-1) ** j * comb(d, j) * count
                return total % MOD

            a = [side(i) for i in range(N + 1)]
            conv = [0] * (N + 1)
            for total in range(N + 1):
                val = 0
                for mid in range(total + 1):
                    left_total = total - mid
                    pair = sum(a[l] * a[left_total - l]
                               for l in range(left_total + 1))
                    val += pow(d, mid, MOD) * pair
                conv[total] = val % MOD
            prefix = [0] * (N + 1)
            for q in range(2, N + 1):
                prefix[q] = conv[q - 2]

        tail = [0] * (N + 1)
        if u == w and v != w:
            return 0
        if v == w:
            if u != v:
                return 0
            for n in range(N + 1):
                tail[n] = surj(n, K - 1)
        else:
            alphabet = [c for c in range(K) if c != w]
            idx = {c: i for i, c in enumerate(alphabet)}
            full = (1 << (K - 1)) - 1
            before = {(True, 0): 1}
            after = {}
            for n in range(1, N + 1):
                nb, na = {}, {}
                for (seen_u, _), ways in before.items():
                    for c in alphabet:
                        if c == v and seen_u:
                            key = (True, 0)
                            na[key] = (na.get(key, 0) + ways) % MOD
                        else:
                            key = (seen_u or c == u, 0)
                            nb[key] = (nb.get(key, 0) + ways) % MOD
                for (_, mask), ways in after.items():
                    for c in alphabet:
                        key = (True, mask | (1 << idx[c]))
                        na[key] = (na.get(key, 0) + ways) % MOD
                before, after = nb, na
                tail[n] = sum(ways for (_, mask), ways in after.items()
                              if mask == full) % MOD
        return sum(prefix[q] * tail[N - q - 1] for q in range(N)) % MOD

    if comb(N, M) < K ** M - 1:
        return 0
    universe = K ** M
    if K ** N <= 700_000 and universe <= 20:
        code = 0
        for a in X:
            code = code * K + a - 1
        target = ((1 << universe) - 1) ^ (1 << code)
        total = 0
        for word in product(range(K), repeat=N):
            layers = [set() for _ in range(M + 1)]
            layers[0].add(())
            found = 0
            for a in word:
                for length in range(M - 1, -1, -1):
                    for p in tuple(layers[length]):
                        if length + 1 == M:
                            c = 0
                            for d in p + (a,):
                                c = c * K + d
                            found |= 1 << c
                        else:
                            layers[length + 1].add(p + (a,))
            if found == target:
                total += 1
        return total % MOD
    if M == 2 and K == 2:
        code = (X[0] - 1) * 2 + X[1] - 1
        target = 15 ^ (1 << code)
        states = {(0, 0, 0): 1}
        for _ in range(N):
            nxt = {}
            for (c0, c1, mask), ways in states.items():
                counts = (c0, c1)
                for a in range(2):
                    nm = mask
                    for b in range(2):
                        if counts[b]:
                            nm |= 1 << (2 * b + a)
                    nc = list(counts)
                    nc[a] = min(2, nc[a] + 1)
                    key = (nc[0], nc[1], nm)
                    nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(v for (_, _, mask), v in states.items() if mask == target) % MOD
    return 0

