from math import isqrt


_DIGIT_MASKS = tuple(1 << (4 * digit) for digit in range(10))
_ASCII_DIGIT_MASKS = tuple(
    _DIGIT_MASKS[code - 48] if 48 <= code <= 57 else 0
    for code in range(128)
)
_ZERO_MASK = _DIGIT_MASKS[0]


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square numbers whose n-digit zero-padded digits match s."""
    target_counts = [0] * 10
    target = 0
    for digit in s:
        value = ord(digit) - 48
        target_counts[value] += 1
        target += _DIGIT_MASKS[value]

    last_root = isqrt(10 ** n - 1)
    if n < 2:
        bases = range(last_root + 1)
        modulus = 0
    else:
        # LCM(10**suffix_digits, 9) fixes the exact suffix and digit-sum
        # residue. This lets us skip entire root residue classes safely.
        suffix_digits = min(n, 3)
        suffix_modulus = 10 ** suffix_digits
        modulus = suffix_modulus * 9
        square_residues = {value * value % modulus for value in range(modulus)}
        allowed = set()
        for residue in square_residues:
            suffix = residue % suffix_modulus
            needed = [0] * 10
            for _ in range(suffix_digits):
                suffix, digit = divmod(suffix, 10)
                needed[digit] += 1
            if all(needed[digit] <= target_counts[digit] for digit in range(10)):
                allowed.add(residue)

        bases = [
            residue
            for residue in range(modulus)
            if residue * residue % modulus in allowed
        ]

    count = 0
    if modulus:
        for base in bases:
            for root in range(base, last_root + 1, modulus):
                digits = str(root * root)
                signature = (n - len(digits)) * _ZERO_MASK
                for character in digits:
                    signature += _ASCII_DIGIT_MASKS[ord(character)]
                if signature == target:
                    count += 1
    else:
        for root in bases:
            digits = str(root * root)
            signature = (n - len(digits)) * _ZERO_MASK
            for character in digits:
                signature += _ASCII_DIGIT_MASKS[ord(character)]
            if signature == target:
                count += 1
    return count
